// ─── NAVBAR ───────────────────────────────────────────────────────────────────
// Transparent at the top of the page, transitions to solid white on scroll.
// Extremely minimal: logo left, spaced links right, no colored backgrounds.
//
// TO EDIT:
//   · NAV_LINKS  — change text or scroll targets
//   · JOIN_LINK  — update the "Join" label & href
// ──────────────────────────────────────────────────────────────────────────────

"use client";

import { useState, useEffect } from "react";
import { Menu, X } from "lucide-react";

// ─── EDIT NAV LINKS ───────────────────────────────────────────────────────────
const NAV_LINKS = [
  { label: "About",    href: "#mission" },
  { label: "Projects", href: "#projects" },
  { label: "Team",     href: "#team" },
];

const JOIN_LINK = { label: "Join", href: "#join" };
// ─────────────────────────────────────────────────────────────────────────────

export default function Navbar() {
  const [scrolled,  setScrolled]  = useState(false);
  const [menuOpen,  setMenuOpen]  = useState(false);

  // Switch from transparent to white once the user scrolls past ~60 px
  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 60);
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <nav
      className={`
        fixed top-0 left-0 right-0 z-50
        transition-all duration-500 ease-in-out
        ${scrolled
          ? "bg-white/95 backdrop-blur-sm border-b border-rule"
          : "bg-transparent border-b border-white/10"
        }
      `}
    >
      <div className="max-w-6xl mx-auto px-8 md:px-16 h-16 flex items-center justify-between">

        {/* ── Logo ── */}
        {/*
          Plain <img> (not Next.js <Image>) so that height/width CSS is respected
          without the component overriding it.
          height: 36px  →  auto width ≈ 83px at the 1406:768 logo ratio.
          ← Change the height value below to resize the navbar logo.

          When not scrolled (transparent nav over dark hero):
            brightness(0) invert(1) turns the logo into a white silhouette.
          When scrolled (white nav):
            no filter — original black + red logo shows normally.
        */}
        <a href="#" className="flex items-center group">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src="/logo.png"
            alt="Brown Analytics Group"
            style={{
              height: "36px",                                        // ← navbar logo height
              width: "auto",
              filter: scrolled ? "none" : "brightness(0) invert(1)",
              transition: "filter 0.4s ease, opacity 0.4s ease",
            }}
          />
        </a>

        {/* ── Desktop links ── */}
        <div className="hidden md:flex items-center gap-10">
          {NAV_LINKS.map((link) => (
            <a
              key={link.label}
              href={link.href}
              className={`
                text-[11px] font-sans font-medium tracking-[0.16em] uppercase
                transition-colors duration-300 relative group/link
                ${scrolled ? "text-mid hover:text-ink" : "text-white/70 hover:text-white"}
              `}
            >
              {link.label}
              {/* Thin seal-brown underline on hover */}
              <span className="absolute -bottom-0.5 left-0 w-0 h-px bg-seal-brown group-hover/link:w-full transition-all duration-300" />
            </a>
          ))}

          {/* Join link — ghost style, no solid fill */}
          <a
            href={JOIN_LINK.href}
            className={`
              text-[11px] font-sans font-medium tracking-[0.16em] uppercase
              px-5 py-2 border transition-all duration-300
              ${scrolled
                ? "border-ink text-ink hover:bg-ink hover:text-white"
                : "border-white/60 text-white hover:bg-white hover:text-ink"
              }
            `}
          >
            {JOIN_LINK.label}
          </a>
        </div>

        {/* ── Mobile hamburger ── */}
        <button
          className={`md:hidden transition-colors duration-300 ${scrolled ? "text-ink" : "text-white"}`}
          onClick={() => setMenuOpen(!menuOpen)}
          aria-label="Toggle navigation"
        >
          {menuOpen ? <X size={20} /> : <Menu size={20} />}
        </button>
      </div>

      {/* ── Mobile dropdown ── */}
      {menuOpen && (
        <div className="md:hidden bg-white border-t border-rule px-8 py-6 flex flex-col gap-6">
          {NAV_LINKS.map((link) => (
            <a
              key={link.label}
              href={link.href}
              className="text-[11px] font-medium tracking-[0.18em] uppercase text-mid hover:text-ink transition-colors"
              onClick={() => setMenuOpen(false)}
            >
              {link.label}
            </a>
          ))}
          <a
            href={JOIN_LINK.href}
            className="self-start text-[11px] font-medium tracking-[0.18em] uppercase px-5 py-2 border border-ink text-ink hover:bg-ink hover:text-white transition-colors"
            onClick={() => setMenuOpen(false)}
          >
            {JOIN_LINK.label}
          </a>
        </div>
      )}
    </nav>
  );
}
